#!/bin/sh
# Compiles kernel/kernel.c to WebAssembly and embeds it in src/kernel-wasm.js (base64),
# so the solver loads it synchronously in Node, the browser and an AudioWorklet alike.
set -e
cd "$(dirname "$0")/.."
clang --target=wasm32 -O3 -msimd128 -nostdlib -fno-builtin \
  -Wl,--no-entry -Wl,--export-memory -Wl,--initial-memory=1048576 \
  -o kernel/kernel.wasm kernel/kernel.c
node -e '
const b = require("fs").readFileSync("kernel/kernel.wasm").toString("base64");
require("fs").writeFileSync("src/kernel-wasm.js",
  "// generated by kernel/build.sh from kernel/kernel.c: do not edit\nexport const KERNEL_WASM = \"" + b + "\";\n");'
ls -la kernel/kernel.wasm
